Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).

Notation zlen l := (Z.of_nat (length l)).

(* [comment removed for export] *)
Ltac kxg_vals :=
  repeat match goal with
  | |- context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H := fresh "HR" in kx_range (EVar j) H; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in |- *; clearbody w ]
  end;
  repeat match goal with
  | |- context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H := fresh "HR" in kx_range e H; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in |- *; clearbody w ]
  end.
Ltac kxg_hyp H :=
  repeat match type of H with
  | context [ev ?E ?j] =>
      let w := fresh "v" in
      first [ let H' := fresh "HR" in kx_range (EVar j) H'; set (w := ev E j) in *; clearbody w
            | set (w := ev E j) in *; clearbody w ]
  end;
  repeat match type of H with
  | context [edenot ?E ?e] =>
      let w := fresh "u" in
      first [ let H' := fresh "HR" in kx_range e H'; set (w := edenot E e) in *; clearbody w
            | set (w := edenot E e) in *; clearbody w ]
  end.
Ltac kxg_clear :=
  lazymatch goal with
  | HK : know_ok _ ?E _ _ |- _ =>
      let b := eval unfold E in E in
      repeat match goal with H : context [E] |- _ => clear H end;
      try clear E;
      lazymatch b with kx_env _ ?xs => try clear xs | _ => idtac end
  end.


(* [comment removed for export] *)
Definition w4s33_Ef_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x12 x13 x15 x16 x17 x18 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S3 L3 pt PTR BITS : Z),
    PTR = S3 + pt ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S3 ->
    S3 + L3 <= SS + n ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    8 <= pt ->
    pt + 8 <= L3 ->
    0 <= BITS <= 64 ->
    (forall (PT' : Z) (bw cw : word) (y5 y6 y11 y14 y15 y17 : word),
