(* [comment removed for export] *)
Definition w4s33_EcA_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x12 x13 x14 x15 x16 x17 x18 x20 x21 x22 x23 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S3 L3 PTR PN U BITS : Z),
    PTR = PN + U ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S3 ->
    S3 + L3 <= SS + n ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    S3 < PTR < S3 + 8 ->
    PTR - S3 + 8 <= L3 ->
    0 <= BITS <= 64 ->
    0 <= U <= 8 ->
    S3 <= PN ->
    (forall (B' : Z) (cw : word) (y5 y6 y11 y14 y15 y17 : word),
       B' = BITS - 8 * U ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 x7 x8 x9 x10 y11 x12 (Z_to_bv 64 PN) y14 y15 x16 y17 x18
           (Z_to_bv 64 B') x20 x21 x22 x23 (Z_to_bv 64 PTR) x25 cw x27 x28 x29 x30 x31) F (Z_to_bv 64 0x92864) fc None
           mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 (Z_to_bv 64 U) x12 x13 x14 x15 x16 x17 x18
        (Z_to_bv 64 BITS) x20 x21 x22 x23 (Z_to_bv 64 PTR) x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x92724) fc None
        mm (seg_rom asegs)).

